import backtrader as bt


class MultiTimeframeRSIStrategy(bt.Strategy):
    params = (("rsi_period", 21), ("trade_size", 100))

    def __init__(self):
        self.rsi = bt.indicators.RSI(self.data.close, period=self.p.rsi_period)
        self.rsi_cross_above_70 = bt.indicators.CrossOver(self.rsi, 70.0)
        self.rsi_cross_below_30 = bt.indicators.CrossDown(self.rsi, 30.0)
        self.order = None
        self.timeframe_bars = {5: None, 15: None}
        self._building_bars = {5: None, 15: None}

    def _process_timeframe(self, minutes):
        timestamp = self.data.datetime.datetime(0)
        bucket_minute = (timestamp.minute // minutes) * minutes
        bucket = timestamp.replace(minute=bucket_minute, second=0, microsecond=0)
        current = self._building_bars[minutes]

        if current is None or current["timestamp"] != bucket:
            if current is not None:
                self.timeframe_bars[minutes] = current
            self._building_bars[minutes] = {
                "timestamp": bucket,
                "open": float(self.data.open[0]),
                "high": float(self.data.high[0]),
                "low": float(self.data.low[0]),
                "close": float(self.data.close[0]),
                "volume": float(self.data.volume[0]),
            }
            return

        current["high"] = max(current["high"], float(self.data.high[0]))
        current["low"] = min(current["low"], float(self.data.low[0]))
        current["close"] = float(self.data.close[0])
        current["volume"] += float(self.data.volume[0])

    def notify_order(self, order):
        if order.status in (
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ):
            self.order = None

    def next(self):
        self._process_timeframe(5)
        self._process_timeframe(15)

        if self.order:
            return

        if not self.position:
            if self.rsi[0] < 30.0:
                self.order = self.buy(size=self.p.trade_size)
            elif self.rsi[0] > 70.0:
                self.order = self.sell(size=self.p.trade_size)
        elif self.position.size > 0 and self.rsi_cross_above_70[0] > 0.0:
            self.order = self.close()
        elif self.position.size < 0 and self.rsi_cross_below_30[0] > 0.0:
            self.order = self.close()
